const http = this.helpers.httpRequest;

// ⚙️ CONFIG
async function sendMsg(phone, text) {
  return http({
    method: 'POST',
    url: 'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
    headers: { 'apikey': 'wasapea-evo-key-2026', 'Content-Type': 'application/json' },
    body: { number: phone, text: text }
  });
}


// 📱 SUBSCRIBERS — only 'pro' plan gets threshold alerts
const subscribers = [
  { phone: '573106055920', plan: 'free' },
  // { phone: '573001234567', plan: 'pro' },
];


// ⚠️ THRESHOLDS — customize here
const UMBRAL_ALTO = 3300;
const UMBRAL_BAJO = 3100;

// 1. Fetch TRM
const resp = await http({ method: 'GET', url: 'https://open.er-api.com/v6/latest/USD' });
const cop = resp.rates?.COP || resp.rates?.cop;
if (!cop) throw new Error('TRM API failed');

// 2. Check thresholds
let text = null;
if (cop >= UMBRAL_ALTO) {
  text = '🚨 *ALERTA TRM ALTA* 🚨\n\n' +
    '🇺🇸 1 USD = 🇨🇴 $' + cop.toLocaleString('es-CO') + ' COP\n\n' +
    '⚠️ El dólar superó los $' + UMBRAL_ALTO.toLocaleString('es-CO') + '\n' +
    '📈 Momento de vender dólares o ajustar precios de importación.\n\n' +
    '⚡ *TRM Alertas*';
} else if (cop <= UMBRAL_BAJO) {
  text = '🟢 *ALERTA TRM BAJA* 🟢\n\n' +
    '🇺🇸 1 USD = 🇨🇴 $' + cop.toLocaleString('es-CO') + ' COP\n\n' +
    '✅ El dólar bajó de $' + UMBRAL_BAJO.toLocaleString('es-CO') + '\n' +
    '💡 Buen momento para comprar dólares o importar.\n\n' +
    '⚡ *TRM Alertas*';
}

if (!text) return { sent: 0, trm: cop, message: 'No threshold triggered' };

// 3. Send to pro subscribers only
const results = [];
const proSubs = subscribers.filter(s => s.plan === 'pro' || s.plan === 'trader');
for (const sub of proSubs) {
  try {
    await sendMsg(sub.phone, text);
    results.push({ phone: sub.phone, status: 'sent' });
  } catch (e) {
    results.push({ phone: sub.phone, status: 'error', error: e.message });
  }
}

return { trm: cop, threshold: cop >= UMBRAL_ALTO ? 'ALTO' : 'BAJO', sent: results.length, results };
